/**
 * Turn the package's CHANGELOG.md into a docs page.
 *
 * Generated rather than copied. A hand-maintained second copy of a changelog is
 * wrong the moment a release lands, and this one is written by changesets — so the
 * docs page is derived from the same file npm ships, or it is not worth having.
 *
 * The output is gitignored and regenerated by `pnpm generate`, alongside the
 * fumadocs collection, so no command can run without it.
 *
 * One constraint this puts on changeset prose: anything that looks like JSX has to
 * sit in backticks, because the page is MDX. `<Xray />` is fine, a bare <Xray /> is
 * a build error. That is a loud failure at release time rather than a silent one,
 * which is the right way round.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, '../../CHANGELOG.md');
const target = join(here, '../content/docs/changelog.mdx');

const raw = readFileSync(source, 'utf8');

// Drop the package-name heading: the page has its own title, and two h1s in one
// document is both wrong and visible in the table of contents.
const body = raw.replace(/^#\s+\S+\s*\n+/, '');

const frontmatter = [
  '---',
  'title: Changelog',
  'description: Every released version, and what changed in it.',
  '---',
  '',
  '{/* Generated from CHANGELOG.md by scripts/changelog-page.mjs. Do not edit. */}',
  '',
].join('\n');

writeFileSync(target, frontmatter + body);

const releases = [...body.matchAll(/^## /gm)].length;
console.log(`changelog page ← CHANGELOG.md (${releases} releases)`);
